CustomField.formula:
IF ( DATEVALUE(LastModifiedDate) >= DATE ( YEAR (DATEVALUE(LastModifiedDate)),3,1) + ( 14 - CASE( MOD(DATE ( YEAR (DATEVALUE(LastModifiedDate)),3,1) - DATE (1900,1,7),7) , 0,7,MOD(DATE ( YEAR (DATEVALUE(LastModifiedDate)),3,1) - DATE (1900,1,7),7)) )
&&
DATEVALUE(LastModifiedDate) < DATE ( YEAR (DATEVALUE(LastModifiedDate)),11,1) + ( 7- CASE( MOD(DATE ( YEAR (DATEVALUE(LastModifiedDate)),11,1) - DATE (1900,1,7),7) , 0,7,MOD(DATE ( YEAR (DATEVALUE(LastModifiedDate)),11,1) - DATE (1900,1,7),7)) ),
/*check if the last modified by is filled */ IF(ER_Last_Modified_By_Functional_user__c != null,
/* if true */
HYPERLINK(LEFT($Api.Partner_Server_URL_420, FIND( '/services', $Api.Partner_Server_URL_420)) + '/lightning/r/User/' + ER_Last_Modified_By_Functional_user__c + '/view',ER_Last_Modified_By_Functional_user__r.FirstName + ' ' + ER_Last_Modified_By_Functional_user__r.LastName) + ', ' + TEXT(DAY(DATEVALUE(ER_Last_Modified_Date_Functional_User__c + 2/24))) + '/' + TEXT(MONTH(DATEVALUE(ER_Last_Modified_Date_Functional_User__c + 2/24))) + '/' + TEXT(YEAR(DATEVALUE(ER_Last_Modified_Date_Functional_User__c + 2/24))) + ' ' + TEXT(HOUR(TIMEVALUE(ER_Last_Modified_Date_Functional_User__c + 2/24))) + ':' + TEXT(MINUTE(TIMEVALUE(ER_Last_Modified_Date_Functional_User__c + 2/24))),
/* else */ '')
,
/*check if the last modified by is filled */ IF(ER_Last_Modified_By_Functional_user__c != null,
/* if true */
HYPERLINK(LEFT($Api.Partner_Server_URL_420, FIND( '/services', $Api.Partner_Server_URL_420)) + '/lightning/r/User/' + ER_Last_Modified_By_Functional_user__c + '/view',ER_Last_Modified_By_Functional_user__r.FirstName + ' ' + ER_Last_Modified_By_Functional_user__r.LastName) + ', ' + TEXT(DAY(DATEVALUE(ER_Last_Modified_Date_Functional_User__c+ 1/24))) + '/' + TEXT(MONTH(DATEVALUE(ER_Last_Modified_Date_Functional_User__c+ 1/24))) + '/' + TEXT(YEAR(DATEVALUE(ER_Last_Modified_Date_Functional_User__c+ 1/24))) + ' ' + TEXT(HOUR(TIMEVALUE(ER_Last_Modified_Date_Functional_User__c+ 1/24))) + ':' + TEXT(MINUTE(TIMEVALUE(ER_Last_Modified_Date_Functional_User__c+ 1/24))),
/* else */ '')
)
